/// Analyzes one surviving file and pushes the annotated blocks that contain a matching line onto `out`.
fn retrieve_blocks(
    ctx: &FileContext<'_>,
    path: &Utf8Path,
    hits: &[LineHit],
    read: &dyn Fn(&Utf8Path) -> io::Result<Source>,
    out: &mut Vec<(CodeBlock, Vec<String>)>,
    diagnostics: &mut Vec<Diagnostic>,
) {
