    r = subprocess.run([binary, "search", q, "."], cwd=W / "target/rg-compare" / repo, capture_output=True, text=True, env=e)
    return parse(r.stdout)


def table():
    res = {q['id']: q for q in json.load(open(B / 'results.json'))}
    out = []
    for line in (B / 'table.md').read_text().splitlines():
        if not line.startswith('| '): continue
        c = [x.strip() for x in line.strip('|').split('|')]
        if len(c) < 6 or not c[0].isdigit(): continue
        repo, q = c[1].split(': ', 1)
        key = next((k for k in (f"Q:{repo}:{q}", f"I:{repo}:{q}") if k in res), None)
